package varify.generator

import varify.config.*

interface Generator<out V> {

    val key: GeneratorKey

    fun generate(randomizer: Randomizer): Sequence<Sample<V>>

    /**
     * Rebuilds [sample], which may have been shrunk, as if this generator had generated it from the same source samples.
     *
     * The shrinking stage rebuilds the samples of earlier attempts with the generator that the test requests in the
     * current attempt, so that combinators apply their current functions. These may capture earlier samples that shrank
     * in the meantime. [sample] was generated by a generator with the same key, so combinators can rely on its type.
     */
    @Suppress("UNCHECKED_CAST")
    fun rebuild(sample: Sample<*>): Sample<V> =
        sample as Sample<V>
}

inline fun <reified G : Generator<*>> generatorKey(vararg properties: Any): GeneratorKey =
    GeneratorKey(G::class, properties.toList())
